import { useGLTF } from "@react-three/drei"
import * as THREE from "three"

// Generated by apps/web/scripts/blender/build-world.py. Every prop shares one vertex-colored
// material, so each prop type costs a single draw call when instanced.
export const WORLD_MODEL_URL = `${import.meta.env.BASE_URL}models/world.glb`

export type PropName =
  | "Bench"
  | "Cloud"
  | "Die"
  | "Flower"
  | "Hill"
  | "Lantern"
  | "MarketStall"
  | "Mushroom"
  | "Rock"
  | "Shrub"
  | "StartGate"
  | "Tile"
  | "TreeOakA"
  | "TreeOakB"
  | "TreePine"

export const propMaterial = new THREE.MeshStandardMaterial({
  vertexColors: true,
  roughness: 0.88,
  metalness: 0,
})

export function usePropGeometry(name: PropName): THREE.BufferGeometry {
  const { nodes } = useGLTF(WORLD_MODEL_URL, false)
  const node = nodes[name]
  if (!(node instanceof THREE.Mesh)) throw new Error(`world.glb is missing the ${name} prop`)
  return node.geometry as THREE.BufferGeometry
}

export type Placement = {
  position: readonly [number, number, number]
  /** Euler rotation in radians, or a yaw around Y when a single number. */
  rotation?: number | readonly [number, number, number]
  scale?: number | readonly [number, number, number]
  color?: string
}

/** Converts a position given relative to a yawed parent into world space. */
export function offsetFrom(
  origin: readonly [number, number, number],
  yaw: number,
  local: readonly [number, number, number],
): [number, number, number] {
  const cos = Math.cos(yaw)
  const sin = Math.sin(yaw)
  return [
    origin[0] + local[0] * cos + local[2] * sin,
    origin[1] + local[1],
    origin[2] - local[0] * sin + local[2] * cos,
  ]
}

export function treeVariant(x: number, z: number): "TreeOakA" | "TreeOakB" | "TreePine" {
  const hash = Math.abs(Math.round(x * 7.3 + z * 3.1)) % 5
  return hash === 0 ? "TreePine" : hash % 2 ? "TreeOakA" : "TreeOakB"
}
